    expect(panel.querySelector('h2')).toBeNull();
    await view.rerender(
      <Drawer variant='detail' open={false} isOpen onClose={() => undefined}>
        body
      </Drawer>
    );
    expect(view.container.querySelector('aside')).toBeNull();
    await view.rerender(
      <Drawer variant='detail' onClose={() => undefined}>
        body
      </Drawer>
    );
    expect(view.container.querySelector('aside')).toBeNull();
